"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["19904"],{32663(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.cotas_da_lei_diferentes_entre_ofertas","status":422,"titulo":"Os cursos do processo ofertam conjuntos diferentes de cotas da lei"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.cotas_da_lei_diferentes_entre_ofertas","requisitos":[],"oQueAconteceu":["Pelo menos dois cursos do processo ofertam conjuntos diferentes de modalidades de cota\\nda lei: um deles oferta uma cota que o outro n\xe3o oferta. A op\xe7\xe3o pelas cotas \xe9 feita\\npela pessoa candidata no processo, e n\xe3o curso a curso. Quem optou por elas perderia,\\nno curso sem a cota, a a\xe7\xe3o afirmativa que l\xe1 lhe caberia; por isso todos os cursos\\ndo processo ofertam as mesmas cotas. A recusa sai com **422**.","A distribui\xe7\xe3o de vagas pode ser gravada assim em rascunho, enquanto o processo est\xe1\\nsendo montado. \xc9 a publica\xe7\xe3o e a retifica\xe7\xe3o em ato \xfanico, que geram vers\xe3o, que barram\\no estado, antes de qualquer grava\xe7\xe3o. A consulta\\nde conformidade do processo (`GET /api/selecao/processos-seletivos/{id}/conformidade`)\\nmostra a pend\xeancia antes da tentativa."],"comoResolver":["Redefina a distribui\xe7\xe3o de vagas\\n(`PUT /api/selecao/processos-seletivos/{id}/distribuicao-vagas`) de modo que todas as\\nofertas de curso tenham as mesmas modalidades de cota da lei: ofere\xe7a a cota que falta\\nno curso que n\xe3o a tem ou retire-a dos demais, conforme o edital. Repita ent\xe3o a\\npublica\xe7\xe3o ou a retifica\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);